{"content":[{"type":"text","text":"import { cleanup, fireEvent, render, screen, within } from "@testing-library/react";
import type { MouseEvent as ReactMouseEvent } from "react";
import { MemoryRouter } from "react-router";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

import { consoleI18n } from "../i18n/i18n";
import {
  ConsoleErrorBoundary,
  ConsoleSessionStatus,
  ConsoleShell,
  LoginHandoff,
  LoginRoute,
  type ConsoleShellContext,
} from "./ConsoleShell";

const authenticatedContext: ConsoleShellContext = {
  kind: "authenticated",
  principalName: "Avery Chen",
  scope: {
    id: "scope-platform",
    name: "Platform Engineering",
  },
};

describe("ConsoleShell", () => {
  afterEach(() => {
    cleanup();
  });

  beforeEach(async () => {
    await consoleI18n.changeLanguage("en-US");
  });

  it("uses the login handoff instead of rendering application chrome without an authorized context", () => {
    const view = render(
      <MemoryRouter>
        <ConsoleShell attentionCount={0} context={{ kind: "anonymous" }}>
          <h1>Unreachable content</h1>
        </ConsoleShell>
      </MemoryRouter>,
    );

    expect(within(view.container).getByRole("main", { name: "Open Agent Cluster Console" })).toBeVisible();
    expect(screen.queryByText("Unreachable content")).not.toBeInTheDocument();
  });

  it("hands an anonymous visitor to the login route without making a platform request", () => {
    const onSignIn = vi.fn((event: ReactMouseEvent<HTMLAnchorElement>) => event.preventDefault());

    const view = render(<LoginHandoff onSignIn={onSignIn} />);
    const signIn = within(view.container).getByRole("link", { name: "Sign in" });

    fireEvent.click(signIn);

    expect(onSignIn).toHaveBeenCalledOnce();
    expect(signIn).toHaveAttribute("href", "/login");
  });

  it("renders a distinct login route after the handoff", () => {
    const view = render(
      <MemoryRouter initialEntries={["/login"]}>
        <LoginRoute locale="en-US" />
      </MemoryRouter>,
    );

    expect(within(view.container).getByRole("heading", { name: "Sign in" })).toBeVisible();
    expect(within(view.container).getByRole("link", { name: "Back to Console" })).toHaveAttribute("href", "/");
  });

  it("keeps session infrastructure failures out of the anonymous handoff and supports a bounded retry", () => {
    const onRetry = vi.fn();
    const view = render(<ConsoleSessionStatus kind="unavailable" onRetry={onRetry} />);

    expect(within(view.container).getByRole("alert")).toHaveTextContent("Console temporarily unavailable");
    fireEvent.click(within(view.container).getByRole("button", { name: "Try again" }));

    expect(onRetry).toHaveBeenCalledOnce();
  });

  it("announces session resolution while authorization is still unknown", () => {
    const view = render(<ConsoleSessionStatus kind="resolving" />);

    expect(within(view.container).getByRole("status")).toHaveTextContent("Loading Console");
  });

  it("keeps the authorized Scope, global navigation, and attention entry in application chrome", () => {
    const view = render(
      <MemoryRouter initialEntries={["/projects"]}>
        <ConsoleShell context={authenticatedContext} attentionCount={3}>
          <h1>Projects</h1>
        </ConsoleShell>
      </MemoryRouter>,
    );

    expect(screen.getByRole("banner")).toHaveTextContent("Platform Engineering");
    expect(screen.getByRole("navigation", { name: "Console navigation" })).toHaveTextContent(
      "Projects",
    );
    expect(screen.getByRole("link", { name: "Projects" })).toHaveAttribute("aria-current", "page");
    expect(screen.getByRole("link", { name: "Workflows" })).toHaveAttribute("href", "/workflows");
    expect(screen.getByRole("link", { name: "Attention, 3 items" })).toHaveAttribute(
      "href",
      "/attention",
    );
    expect(within(view.container).getByRole("main")).toHaveTextContent("Projects");
  });

  it("renders Simplified Chinese labels and exposes a keyboard-native language change control", async () => {
    await consoleI18n.changeLanguage("zh-CN");
    const onLanguageChange = vi.fn();

    const view = render(
      <MemoryRouter initialEntries={["/projects"]}>
        <ConsoleShell context={authenticatedContext} attentionCount={3} locale="zh-CN" onLanguageChange={onLanguageChange}>
          <h1>项目</h1>
        </ConsoleShell>
      </MemoryRouter>,
    );

    expect(within(view.container).getByRole("navigation", { name: "控制台导航" })).toBeVisible();
    expect(within(view.container).getByRole("link", { name: "待处理，3 项" })).toHaveAttribute("href", "/attention");
    expect(within(view.container).getByRole("radio", { name: "中文" })).toHaveAttribute("aria-checked", "true");

    fireEvent.keyDown(within(view.container).getByRole("radio", { name: "中文" }), { key: "ArrowRight" });

    expect(onLanguageChange).toHaveBeenCalledWith("en-US");
  });

  it("shows a safe error fallback with a canonical code when shell content throws", () => {
    const ThrowingContent = () => {
      throw new Error("unexpected test failure");
    };

    const consoleError = vi.spyOn(console, "error").mockImplementation(() => undefined);

    render(
      <ConsoleErrorBoundary>
        <ThrowingContent />
      </ConsoleErrorBoundary>,
    );

    expect(screen.getByRole("alert")).toHaveTextContent("We couldn't load this Console surface.");
    expect(screen.getByText("UI_UNEXPECTED_ERROR")).toBeVisible();
    consoleError.mockRestore();
  });
});
});

test("console-shell keeps a network session failure distinct from anonymous access", async ({ page }) => {
  await page.route("**/api/console/session", (route) => route.abort("failed"));
  await page.goto("/");

  await expectUnavailableSession(page);
});

