  await expect(page.getByRole("link", { name: "项目" })).toHaveAttribute("aria-current", "page");
  await expect(page.getByRole("link", { name: "待处理，3 项" })).toHaveAttribute(
    "href",
    "/attention",
  );
  await expect(page.locator("#console-content")).toContainText("选择一个控制台路由");
  await expect(page.getByRole("radio", { name: "中文" })).toHaveAttribute("aria-checked", "true");
  await expect(page.locator("html")).toHaveAttribute("lang", "zh-CN");

  await page.getByRole("radio", { name: "English" }).click();

